arguments.argument:
if !key_check
{
    ime_set_language(language)
    keyboard_string=""
    key_check=1
    exit
}

if keyboard_string!=""
{
    language=ime_get_language()
    ime_set_language(0)
    key_check=0
    if global.player_com_ai and keyboard_string="백만장자"
    {
        global.player_moni[global.player_control]+=5000
    }
    else if global.player_com_ai and keyboard_string="내눈을바라봐"
    {
        global.map_heck=1
    }
    else if string_copy(keyboard_string, 1, 1)!="!"
    {
        ds_list_add(key, room_speed*5)
        ds_list_add(key, global.player_control)
        ds_list_add(key, global.name+" : "+keyboard_string)
        /*on*/buffer_clear(fnv_sned)
        write_ubyte(fnv_sned, global.player_control)
        write_string_v2(fnv_sned, global.name+" : "+keyboard_string)
        fn_message_send(global.socket, send_other, 11)
    }
    else
    {
        with(sys_mouse)
        {
            for(i=0; i!=vab_unit; i+=1)
            {
                if instance_number(vab_unit_id[i])
                {
                    if global.player_control=vab_unit_id[i].player or global.map_heck
                    {
                        vab_unit_id[i].v_name=string_copy(keyboard_string, 2, string_length(keyboard_string))
                        /*on*/buffer_clear(fnv_sned)
                        write_uint(fnv_sned, vab_unit_id[i].on)
                        write_string_v2(fnv_sned, vab_unit_id[i].v_name)
                        fn_message_send(global.socket, send_other, 29)
                    }
                }
            }
        }
    }
    keyboard_string=""
}
else
{
    key_check=0
}
